import { esc, icon, badge, avatar, progress, empty, fmt, money } from './ui.js';
import { handleOrganization } from './organization.js';

let goalFilter = 'all';
let decisionFilter = 'pending';
let gapFilter = 'all';
let policyFilter = 'all';
const statusNames = {'on-track':'En bonne voie','at-risk':'À surveiller','off-track':'En retard'};
const statusTones = {'on-track':'green','at-risk':'amber','off-track':'red'};
const categories = {capacity:'Capacité',capability:'Compétence',authority:'Autorité',data:'Données',adoption:'Adoption'};
const modes = {block:'Bloquer',ask:'Faire valider',log:'Journaliser'};
const types = {approval:'Validation',exception:'Exception',budget:'Budget'};
const teams = ['Opérations','Investissement','Conformité','Distribution'];
const id = prefix => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;
const date = value => { const d = new Date(value); return Number.isNaN(d.getTime()) ? esc(value || '—') : d.toLocaleDateString('fr-FR',{day:'numeric',month:'short'}); };
const ownerInitials = name => String(name || 'MK').split(' ').map(x=>x[0]).slice(0,2).join('');
const ownerAvatar = name => avatar({name,initials:ownerInitials(name),type:'human'});
const opts = (values, selected) => values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
const head = (eyebrow,title,description,action='') => `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-description">${description}</p></div><div class="head-actions">${action}</div></div>`;
const filterBtn = (label,value,current,action,count='') => `<button class="filter-btn ${value===current?'active':''}" data-action="${action}" data-value="${value}" aria-pressed="${value===current}">${label}${count!==''?` <span class="filter-count">${count}</span>`:''}</button>`;
const evidence = items => `<ul class="evidence">${(items||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
const goalStatus = goal => badge(statusNames[goal.status] || 'À surveiller',statusTones[goal.status] || 'amber');
const goalPercent = goal => Math.min(100,Math.max(0,Number(goal.progress)||0));

export function renderGoals(s) {
  const filtered = s.goals.filter(g=>goalFilter==='all'||g.status===goalFilter);
  const onTrack = s.goals.filter(g=>g.status==='on-track').length;
  return `${head('CAP COMMUN','Des objectifs. Des responsables.','Reliez chaque ambition aux équipes, aux processus et aux résultats qui la font avancer.',`<button class="btn btn-primary" data-action="gov-new-goal">${icon('plus',16)} Nouvel objectif</button>`)}
  <div class="notice goal-notice">${icon('target',21)}<div><strong>${onTrack} objectif${onTrack>1?'s':''} sur ${s.goals.length} en bonne voie.</strong> <span class="muted">${s.goals.length-onTrack} demandent votre attention. Chaque résultat a un propriétaire et une échéance.</span></div></div>
  <div class="filter-bar">${filterBtn('Tous les objectifs','all',goalFilter,'gov-goal-filter',s.goals.length)}${filterBtn('En bonne voie','on-track',goalFilter,'gov-goal-filter',onTrack)}${filterBtn('À surveiller','at-risk',goalFilter,'gov-goal-filter')}${filterBtn('En retard','off-track',goalFilter,'gov-goal-filter')}</div>
  <div class="grid-2 goals-grid">${filtered.map(g=>`<article class="card goal-card"><div class="goal-top"><span class="eyebrow">${esc(g.team)}</span>${goalStatus(g)}</div><button class="goal-title-button" data-action="gov-goal-detail" data-id="${esc(g.id)}"><h2 class="card-title">${esc(g.title)}</h2>${icon('arrow',18)}</button><p class="muted small">${esc(g.description)}</p><div class="goal-progress-label"><span>Progression globale</span><strong>${goalPercent(g)}<small>%</small></strong></div>${progress(goalPercent(g),g.status==='off-track'?'red':g.status==='on-track'?'green':'purple')}<div class="kr-list">${g.krs.slice(0,3).map(k=>`<div class="kr-row"><span>${esc(k.label)}</span><strong>${fmt(k.current)}${esc(k.unit==='%'?' %':` ${k.unit||''}`)} <span class="muted">/ ${fmt(k.target)}${esc(k.unit==='%'?' %':'')}</span></strong></div>`).join('')}</div><div class="goal-footer"><div class="person">${ownerAvatar(g.owner)}<span class="small">${esc(g.owner)}</span></div><span class="muted small">${icon('clock',14)} ${date(g.targetDate)}</span></div></article>`).join('') || empty('Aucun objectif dans cette vue','Les objectifs correspondant à ce statut apparaîtront ici.')}</div>`;
}

function goalDrawer(g,s,ctx) {
 const linked = s.processes.filter(p=>(g.processIds||[]).includes(p.id));
 ctx.drawer({title:g.title,subtitle:`${g.team} · ${g.owner}`,body:`<div class="row between">${goalStatus(g)}<span class="muted small">Échéance ${date(g.targetDate)}</span></div><p class="detail-lead">${esc(g.description)}</p><div class="goal-progress-label"><span>Progression</span><strong>${goalPercent(g)} %</strong></div>${progress(goalPercent(g))}<h3 class="section-title">Résultats clés</h3><div class="stack">${g.krs.map(k=>`<div class="card kr-detail"><div class="small muted">${esc(k.label)}</div><div class="metric-inline"><strong>${fmt(k.current)} ${esc(k.unit||'')}</strong><span class="muted">sur ${fmt(k.target)} ${esc(k.unit||'')}</span></div></div>`).join('')}</div><h3 class="section-title">Processus contributeurs</h3>${linked.length?linked.map(p=>`<button class="linked-row" data-action="gov-process-link" data-id="${esc(p.id)}">${icon('workflow',18)}<span>${esc(p.name)}</span>${icon('arrow',16)}</button>`).join(''):`<p class="muted small">Aucun processus associé pour le moment.</p>`}<div class="drawer-actionbar"><button class="btn btn-primary" data-action="gov-edit-goal" data-id="${esc(g.id)}">${icon('edit',16)} Mettre à jour les résultats</button></div>`});
}

function goalForm(g,s,ctx) {
 const isNew = !g;
 const initial = g || {title:'',description:'',owner:'Matthieu',team:'Opérations',targetDate:'2026-12-31',progress:0,status:'on-track',krs:[{label:'',current:0,target:100,unit:'%'}],processIds:[]};
 ctx.closeDrawer();
 ctx.modal({title:isNew?'Définir un objectif':'Mettre à jour l’objectif',subtitle:'Un résultat mesurable, un responsable identifié, une échéance.',submitLabel:isNew?'Créer l’objectif':'Enregistrer les résultats',body:`<div class="field"><label for="goal-title">Objectif</label><input id="goal-title" name="title" value="${esc(initial.title)}" placeholder="Ex. Produire les reportings sous deux jours" required maxlength="160"></div><div class="field"><label for="goal-description">Résultat attendu</label><textarea id="goal-description" name="description" rows="3" required maxlength="700">${esc(initial.description)}</textarea></div><div class="form-grid"><div class="field"><label for="goal-owner">Responsable humain</label><input id="goal-owner" name="owner" value="${esc(initial.owner)}" required maxlength="80"></div><div class="field"><label for="goal-team">Équipe</label><select id="goal-team" name="team">${opts(teams,initial.team)}</select></div><div class="field"><label for="goal-date">Échéance</label><input id="goal-date" name="targetDate" type="date" value="${esc(initial.targetDate?.slice(0,10))}" required></div><div class="field"><label for="goal-status">Situation</label><select id="goal-status" name="status">${Object.entries(statusNames).map(([key,value])=>`<option value="${key}" ${key===initial.status?'selected':''}>${value}</option>`).join('')}</select></div><div class="field"><label for="goal-progress">Progression globale (%)</label><input id="goal-progress" name="progress" type="number" min="0" max="100" value="${goalPercent(initial)}" required></div></div><h3 class="section-title">Résultats clés</h3>${initial.krs.map((k,i)=>`<div class="card form-kr"><div class="field"><label for="kr-label-${i}">Résultat ${i+1}</label><input id="kr-label-${i}" name="kr-label-${i}" value="${esc(k.label)}" required maxlength="120" placeholder="Ex. Dossiers livrés dans le délai"></div><div class="form-grid"><div class="field"><label for="kr-current-${i}">Valeur actuelle</label><input id="kr-current-${i}" name="kr-current-${i}" type="number" step="any" value="${Number(k.current)||0}" required></div><div class="field"><label for="kr-target-${i}">Cible</label><input id="kr-target-${i}" name="kr-target-${i}" type="number" step="any" value="${Number(k.target)||100}" required></div><div class="field"><label for="kr-unit-${i}">Unité</label><input id="kr-unit-${i}" name="kr-unit-${i}" value="${esc(k.unit||'')}" maxlength="16" placeholder="%, jours, dossiers…"></div></div></div>`).join('')}<div class="field"><label for="goal-process">Processus associé</label><select id="goal-process" name="processId"><option value="">Aucun pour le moment</option>${s.processes.map(p=>`<option value="${esc(p.id)}" ${(initial.processIds||[]).includes(p.id)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>`,onSubmit:data=>{
  const title=String(data.get('title')||'').trim(), owner=String(data.get('owner')||'').trim();
  if(!title||!owner){ctx.toast('Renseignez un objectif et son responsable.');return false;}
  const krs=initial.krs.map((k,i)=>({label:String(data.get(`kr-label-${i}`)||'').trim(),current:Number(data.get(`kr-current-${i}`)),target:Number(data.get(`kr-target-${i}`)),unit:String(data.get(`kr-unit-${i}`)||'').trim()}));
  if(krs.some(k=>!k.label||!Number.isFinite(k.current)||!Number.isFinite(k.target))){ctx.toast('Vérifiez les résultats clés.');return false;}
  const record={...initial,id:g?.id||id('goal'),title,owner,team:String(data.get('team')),description:String(data.get('description')||'').trim(),targetDate:String(data.get('targetDate')),status:String(data.get('status')),progress:Math.max(0,Math.min(100,Number(data.get('progress'))||0)),krs,processIds:data.get('processId')?[String(data.get('processId'))]:[]};
  ctx.update(st=>{if(isNew)st.goals.unshift(record);else Object.assign(st.goals.find(x=>x.id===g.id),record);},isNew?'Objectif créé':'Résultats actualisés',title);
  ctx.toast(isNew?'L’objectif est créé.':'Les résultats ont été mis à jour.');
 }});
}

export function renderDecisions(s) {
 const pending=s.decisions.filter(d=>d.status==='pending');
 const filtered=s.decisions.filter(d=>decisionFilter==='all'||(decisionFilter==='handled'?d.status!=='pending':d.status==='pending'));
 return `${head('VOTRE FILE DE DÉCISION','Le bon jugement. Au bon moment.','Les agents vous passent la main avec le contexte, les preuves et une recommandation.')}
 <div class="stat-grid decision-stats"><div class="stat-card"><span class="stat-label">À arbitrer</span><strong class="stat-value">${pending.length}</strong><span class="stat-foot">Décisions sous votre responsabilité</span></div><div class="stat-card"><span class="stat-label">Priorité haute</span><strong class="stat-value">${pending.filter(d=>d.priority==='high').length}</strong><span class="stat-foot">À examiner en premier</span></div><div class="stat-card"><span class="stat-label">Décisions traitées</span><strong class="stat-value">${s.decisions.length-pending.length}</strong><span class="stat-foot">Avec une trace dans le journal</span></div></div>
 <div class="filter-bar">${filterBtn('À traiter','pending',decisionFilter,'gov-decision-filter',pending.length)}${filterBtn('Traitées','handled',decisionFilter,'gov-decision-filter',s.decisions.length-pending.length)}${filterBtn('Toutes','all',decisionFilter,'gov-decision-filter')}</div>
 <div class="stack decision-list">${filtered.map(d=>{
  const agent=s.agents.find(a=>a.id===d.agentId), process=s.processes.find(p=>p.id===d.processId);
  return `<article class="card decision-card"><div class="decision-card-main"><div class="decision-icon ${d.priority==='high'?'priority-high':''}">${icon(d.type==='budget'?'sliders':d.type==='exception'?'alert':'inbox',21)}</div><div class="decision-copy"><div class="row decision-meta">${badge(types[d.type]||'Validation','purple')}${d.status==='pending'?badge(d.priority==='high'?'Priorité haute':'À examiner',d.priority==='high'?'amber':'neutral'):badge(d.status==='approved'?'Approuvée':'Refusée',d.status==='approved'?'green':'red')}<span class="muted small">${date(d.createdAt)}</span></div><button class="decision-title-button" data-action="gov-decision-detail" data-id="${esc(d.id)}"><h2 class="card-title">${esc(d.title)}</h2></button><p class="muted small">${esc(d.summary)}</p><div class="decision-source">${agent?avatar(agent):icon('bot',18)}<span>${esc(agent?.name||'Agent')} <span class="muted">· ${esc(process?.name||'Décision manuelle')}</span></span></div></div></div><button class="btn ${d.status==='pending'?'btn-primary':'btn-ghost'} btn-sm" data-action="gov-decision-detail" data-id="${esc(d.id)}">${d.status==='pending'?'Examiner':'Voir la décision'} ${icon('arrow',15)}</button></article>`;
 }).join('')||empty('Tout est à jour','Aucune décision dans cette vue. Vous pouvez lancer un processus pour explorer le circuit de validation.')}</div>`;
}

function decisionDrawer(d,s,ctx) {
 const agent=s.agents.find(a=>a.id===d.agentId), goal=s.goals.find(g=>g.id===d.goalId), process=s.processes.find(p=>p.id===d.processId);
 ctx.drawer({title:d.title,subtitle:`${types[d.type]||'Validation'} · ${agent?.name||'Agent'}`,body:`<div class="row between">${badge(d.status==='pending'?'Votre décision est attendue':d.status==='approved'?'Approuvée':'Refusée',d.status==='pending'?'amber':d.status==='approved'?'green':'red')}<span class="muted small">${d.dueAt?`Échéance ${date(d.dueAt)}`:''}</span></div><p class="detail-lead">${esc(d.summary)}</p><div class="detail-grid"><div class="detail-item"><span class="muted small">Agent responsable</span><strong>${esc(agent?.name||'—')}</strong></div><div class="detail-item"><span class="muted small">Processus</span><strong>${esc(process?.name||'—')}</strong></div>${d.amount?`<div class="detail-item"><span class="muted small">Montant concerné</span><strong>${money(d.amount)}</strong></div>`:''}<div class="detail-item"><span class="muted small">Responsable humain</span><strong>${esc(d.assignedTo||agent?.manager||'Matthieu')}</strong></div></div><h3 class="section-title">Éléments à votre disposition</h3>${evidence(d.evidence)}<div class="recommendation"><div class="row">${icon('bot',19)}<strong>Recommandation de l’agent</strong></div><p>${esc(d.recommendation)}</p></div>${goal?`<h3 class="section-title">Objectif concerné</h3><button class="linked-row" data-action="gov-goal-detail" data-id="${esc(goal.id)}">${icon('target',18)}<span>${esc(goal.title)}</span>${icon('arrow',16)}</button>`:''}${d.status!=='pending'?`<div class="notice"><div><strong>Décision enregistrée</strong><p>${esc(d.comment||'Sans commentaire complémentaire.')}</p></div></div>`:`<div class="drawer-actionbar"><button class="btn btn-primary" data-action="gov-review-decision" data-id="${esc(d.id)}" data-value="approved">${icon('check',16)} Approuver</button><button class="btn" data-action="gov-review-decision" data-id="${esc(d.id)}" data-value="rejected">${icon('x',16)} Refuser</button><button class="btn btn-ghost" data-action="gov-reassign-decision" data-id="${esc(d.id)}">Réaffecter</button></div><p class="form-help">Votre décision est liée à cette demande et enregistrée dans le journal.</p>`}`});
}

export function renderGaps(s) {
 const open=s.gaps.filter(g=>g.status==='open');
 const filtered=s.gaps.filter(g=>gapFilter==='resolved'?g.status==='resolved':g.status==='open'&&(gapFilter==='all'||g.category===gapFilter));
 return `${head('DIAGNOSTIC DE L’ORGANISATION','Ce qui freine vos objectifs.','Identifiez la cause, examinez les preuves et choisissez comment débloquer le travail.')}
 <div class="notice gap-notice">${icon('alert',23)}<div><strong>${open.length} points de blocage ouverts.</strong> <span class="muted">Les actions proposées sont des pistes à arbitrer. Leur impact est estimé.</span></div></div>
 <div class="filter-bar wrap-filters">${filterBtn('Tous','all',gapFilter,'gov-gap-filter',open.length)}${Object.entries(categories).map(([key,label])=>filterBtn(label,key,gapFilter,'gov-gap-filter')).join('')}${filterBtn('Plans engagés','resolved',gapFilter,'gov-gap-filter',s.gaps.length-open.length)}</div>
 <div class="stack">${filtered.map((g,i)=>{
  const goal=s.goals.find(x=>x.id===g.goalId);
  return `<details class="card gap-card" ${i===0?'open':''}><summary class="gap-summary"><div class="icon-box ${g.impact==='high'?'amber':'purple'}">${icon(g.category==='authority'?'shield':g.category==='data'?'plug':g.category==='capacity'?'users':g.category==='capability'?'bot':'activity',21)}</div><div class="gap-summary-copy"><div class="row"><h2 class="card-title">${esc(g.title)}</h2>${g.status==='resolved'?badge('Plan engagé','green'):badge(g.impact==='high'?'Impact élevé':'À arbitrer',g.impact==='high'?'amber':'neutral')}</div><span class="muted small">${categories[g.category]||esc(g.category)} · ${esc(g.team)}</span></div><span class="details-chevron">${icon('chevron',18)}</span></summary><div class="gap-content"><p>${esc(g.summary)}</p>${goal?`<div class="gap-goal"><span class="muted small">Objectif concerné</span><button data-action="gov-goal-detail" data-id="${esc(goal.id)}" class="text-link">${esc(goal.title)} ${icon('arrow',13)}</button></div>`:''}${evidence(g.evidence)}<h3 class="section-title">${g.status==='resolved'?'Action retenue':'Vos options'}</h3><div class="stack">${(g.options||[]).filter(o=>g.status!=='resolved'||!g.resolvedOption||o.id===g.resolvedOption).map(o=>`<div class="option-row"><div class="option-icon">${icon(o.action==='train'?'bot':o.action==='connect'?'plug':o.action==='reassign'?'users':'check',18)}</div><div><strong>${esc(o.label)}</strong><p class="small muted">${esc(o.description)}</p><span class="option-impact">${esc(o.impact)}</span></div>${g.status==='open'?`<button class="btn btn-sm" data-action="gov-gap-action" data-id="${esc(g.id)}" data-option="${esc(o.id)}">Choisir ${icon('arrow',14)}</button>`:badge('Retenue','green')}</div>`).join('')}</div></div></details>`;
 }).join('')||empty('Aucun point de blocage','Les problèmes correspondant à cette catégorie apparaîtront ici.')}</div>`;
}

export function renderPolicies(s) {
 const filtered=s.policies.filter(p=>policyFilter==='all'||p.category===policyFilter);
 return `${head('CADRE COMMUN','Une autonomie avec des limites claires.','Des règles partagées, un propriétaire identifié et une réponse explicite à chaque situation.',`<button class="btn btn-primary" data-action="gov-new-policy">${icon('plus',16)} Nouvelle règle</button>`)}
 <div class="notice">${icon('shield',22)}<div><strong>${s.policies.filter(p=>p.enabled).length} règles actives.</strong> <span class="muted">Les mandats des agents précisent leur périmètre à l’intérieur de ce cadre.</span></div></div>
 <div class="filter-bar">${filterBtn('Toutes','all',policyFilter,'gov-policy-filter')}${['Données','Autorité','Budget','Sécurité'].map(c=>filterBtn(c,c,policyFilter,'gov-policy-filter')).join('')}</div>
 <div class="grid-2 policies-grid">${filtered.map(p=>`<article class="card policy-item"><div class="policy-header"><span class="eyebrow">${esc(p.category)}</span>${badge(p.enabled?'Active':'Inactive',p.enabled?'green':'neutral')}</div><h2 class="card-title">${esc(p.title)}</h2><p class="muted small policy-rule">${esc(p.rule)}</p>${!p.check?'<p class="declarative-label">Règle déclarative · activation moteur à définir</p>':''}<div class="tag-list"><span class="tag">${icon(p.mode==='block'?'lock':p.mode==='ask'?'user':'history',13)} ${modes[p.mode]||esc(p.mode)}</span><span class="tag">${esc(p.scope)}</span></div><div class="policy-footer"><span class="muted small">${esc(p.owner)}</span><button class="btn btn-ghost btn-sm" data-action="gov-policy-detail" data-id="${esc(p.id)}">Détails ${icon('arrow',14)}</button></div></article>`).join('')||empty('Aucune règle dans cette catégorie','Créez une règle pour définir le cadre attendu.')}</div>`;
}

function policyForm(p,ctx) {
 const isNew=!p, initial=p||{title:'',category:'Autorité',scope:'Toute l’organisation',rule:'',mode:'ask',owner:'Matthieu',enabled:false};
 ctx.closeDrawer();
 ctx.modal({title:isNew?'Définir une règle':'Modifier la règle',subtitle:'Décrivez la limite et la manière dont elle doit être traitée.',submitLabel:isNew?'Créer la règle':'Enregistrer',body:`<div class="field"><label for="policy-title">Nom de la règle</label><input id="policy-title" name="title" required maxlength="140" value="${esc(initial.title)}" placeholder="Ex. Publication externe après validation"></div><div class="field"><label for="policy-rule">Règle</label><textarea id="policy-rule" name="rule" required rows="4" maxlength="1000">${esc(initial.rule)}</textarea></div><div class="form-grid"><div class="field"><label for="policy-category">Catégorie</label><select id="policy-category" name="category">${opts(['Données','Autorité','Budget','Sécurité'],initial.category)}</select></div><div class="field"><label for="policy-mode">Traitement attendu</label><select id="policy-mode" name="mode">${Object.entries(modes).map(([key,val])=>`<option value="${key}" ${key===initial.mode?'selected':''}>${val}</option>`).join('')}</select></div><div class="field"><label for="policy-owner">Responsable</label><input id="policy-owner" name="owner" value="${esc(initial.owner)}" required maxlength="80"></div><div class="field"><label for="policy-scope">Périmètre</label><input id="policy-scope" name="scope" value="${esc(initial.scope)}" required maxlength="100"></div></div><p class="form-help">Cette règle déclarative sera créée inactive. Son contrôle d’exécution reste à définir et valider avant activation du moteur.</p>`,onSubmit:data=>{
  const record={...initial,id:p?.id||id('policy'),title:String(data.get('title')||'').trim(),rule:String(data.get('rule')||'').trim(),category:String(data.get('category')),mode:String(data.get('mode')),owner:String(data.get('owner')||'').trim(),scope:String(data.get('scope')||'').trim()};
  if(!record.title||!record.rule||!record.owner||!record.scope){ctx.toast('Complétez les champs de la règle.');return false;}
  ctx.update(st=>{if(isNew)st.policies.unshift(record);else Object.assign(st.policies.find(x=>x.id===p.id),record);},isNew?'Règle créée':'Règle modifiée',record.title);ctx.toast(isNew?'La règle est enregistrée.':'La règle est mise à jour.');
 }});
}

function policyDrawer(p,ctx) {
 ctx.drawer({title:p.title,subtitle:`${p.category} · ${p.id}`,body:`<div class="row">${badge(p.enabled?'Active':'Inactive',p.enabled?'green':'neutral')}${badge(modes[p.mode]||p.mode,'purple')}</div><p class="detail-lead">${esc(p.rule)}</p><div class="detail-grid"><div class="detail-item"><span class="muted small">Responsable</span><strong>${esc(p.owner)}</strong></div><div class="detail-item"><span class="muted small">Périmètre</span><strong>${esc(p.scope)}</strong></div></div><h3 class="section-title">Réponse attendue</h3><p class="muted">${p.mode==='block'?'L’action concernée doit être empêchée et l’événement conservé dans le journal.':p.mode==='ask'?'L’action concernée attend une décision du responsable humain avant de continuer.':'L’action peut continuer, avec une trace consultable de la règle et du contexte.'}</p><div class="drawer-actionbar"><button class="btn btn-primary" data-action="gov-edit-policy" data-id="${esc(p.id)}">${icon('edit',16)} Modifier</button><button class="btn" data-action="gov-toggle-policy" data-id="${esc(p.id)}">${icon(p.enabled?'pause':'play',16)} ${p.enabled?'Désactiver':'Activer'}</button></div>`});
}

export function handleGovernance(action,el,ctx) {
 if(!action.startsWith('gov-'))return false;
 const s=ctx.getState(), recordId=el.dataset.id;
 if(action==='gov-goal-filter'){goalFilter=el.dataset.value;ctx.render();return true;}
 if(action==='gov-decision-filter'){decisionFilter=el.dataset.value;ctx.render();return true;}
 if(action==='gov-gap-filter'){gapFilter=el.dataset.value;ctx.render();return true;}
 if(action==='gov-policy-filter'){policyFilter=el.dataset.value;ctx.render();return true;}
 if(action==='gov-new-goal'){goalForm(null,s,ctx);return true;}
 if(action==='gov-edit-goal'){const g=s.goals.find(x=>x.id===recordId);if(g)goalForm(g,s,ctx);return true;}
 if(action==='gov-goal-detail'){const g=s.goals.find(x=>x.id===recordId);if(g)goalDrawer(g,s,ctx);return true;}
 if(action==='gov-process-link'){ctx.closeDrawer();ctx.navigate('processes');handleOrganization('org-process',{dataset:{id:recordId}},ctx);return true;}
 if(action==='gov-decision-detail'){const d=s.decisions.find(x=>x.id===recordId);if(d)decisionDrawer(d,s,ctx);return true;}
 if(action==='gov-review-decision'){
  const d=s.decisions.find(x=>x.id===recordId);if(!d||d.status!=='pending'){ctx.toast('Cette décision a déjà été traitée.');return true;}
  const approved=el.dataset.value==='approved';
  ctx.closeDrawer();ctx.modal({title:approved?'Approuver cette demande':'Refuser cette demande',subtitle:d.title,submitLabel:approved?'Confirmer l’approbation':'Confirmer le refus',body:`<div class="notice"><div><strong>${approved?'L’exécution concernée pourra reprendre.':'L’action proposée ne sera pas exécutée.'}</strong><p class="small muted">${esc(d.summary)}</p></div></div><div class="field"><label for="decision-comment">${approved?'Commentaire ou conditions':'Motif du refus'}</label><textarea id="decision-comment" name="comment" rows="4" ${approved?'':'required'} maxlength="1200" placeholder="${approved?'Précisez ce qui a guidé votre décision…':'Expliquez le changement attendu…'}"></textarea></div><p class="form-help">La décision et votre commentaire seront conservés dans le journal d’activité.</p>`,onSubmit:data=>{
   const comment=String(data.get('comment')||'').trim();if(!approved&&!comment){ctx.toast('Ajoutez le motif du refus.');return false;}
   try{const result=ctx.decide(d.id,approved?'approved':'rejected',comment);if(result?.ok===false){ctx.toast(result.error||'Impossible de traiter cette décision.');return false;}ctx.toast(approved?'Demande approuvée. Le processus a été mis à jour.':'Demande refusée et décision enregistrée.');}catch(error){ctx.toast(error.message||'Impossible de traiter cette décision.');return false;}
  }});return true;
 }
 if(action==='gov-reassign-decision'){
  const d=s.decisions.find(x=>x.id===recordId);if(!d)return true;
  ctx.closeDrawer();ctx.modal({title:'Réaffecter la décision',subtitle:d.title,submitLabel:'Réaffecter',body:`<div class="field"><label for="decision-owner">Responsable</label><select id="decision-owner" name="owner">${opts([...new Set(['Matthieu',...s.agents.filter(a=>a.type==='human').map(a=>a.name)])],d.assignedTo||'Matthieu')}</select></div><div class="field"><label for="decision-note">Contexte transmis</label><textarea id="decision-note" name="note" rows="3" placeholder="Pourquoi cette décision lui revient-elle ?" required maxlength="800"></textarea></div>`,onSubmit:data=>{const note=String(data.get('note')||'').trim();if(!note){ctx.toast('Ajoutez le contexte de la réaffectation.');return false;}ctx.update(st=>{const target=st.decisions.find(x=>x.id===d.id);target.assignedTo=String(data.get('owner'));target.evidence.push(`Réaffectation : ${note}`);},'Décision réaffectée',`${d.title} → ${data.get('owner')}`);ctx.toast('La décision a été réaffectée.');}});return true;
 }
 if(action==='gov-gap-action'){
  const gap=s.gaps.find(x=>x.id===recordId), option=gap?.options.find(x=>x.id===el.dataset.option);if(!gap||!option)return true;
  ctx.modal({title:'Confirmer votre arbitrage',subtitle:gap.title,submitLabel:'Retenir cette action',body:`<div class="notice"><div><strong>${esc(option.label)}</strong><p>${esc(option.description)}</p></div></div><div class="field"><label for="gap-note">Note de décision</label><textarea id="gap-note" name="note" rows="3" maxlength="800" placeholder="Précisez le suivi attendu (facultatif)…"></textarea></div><p class="form-help">Impact estimé : ${esc(option.impact)}. Le plan d’action sera enregistré. Son effet sur les résultats restera à mesurer.</p>`,onSubmit:data=>{try{const result=ctx.resolveGap(gap.id,option.id);if(result?.ok===false){ctx.toast(result.error||'Impossible de retenir cette action.');return false;}const note=String(data.get('note')||'').trim();if(note)ctx.update(st=>{st.gaps.find(x=>x.id===gap.id).decisionNote=note;},'Arbitrage documenté',note);ctx.toast('Votre arbitrage est enregistré.');}catch(error){ctx.toast(error.message||'Impossible de retenir cette action.');return false;}}});return true;
 }
 if(action==='gov-new-policy'){policyForm(null,ctx);return true;}
 if(action==='gov-policy-detail'){const p=s.policies.find(x=>x.id===recordId);if(p)policyDrawer(p,ctx);return true;}
 if(action==='gov-edit-policy'){const p=s.policies.find(x=>x.id===recordId);if(p)policyForm(p,ctx);return true;}
 if(action==='gov-toggle-policy'){
  const p=s.policies.find(x=>x.id===recordId);if(!p)return true;
  ctx.closeDrawer();ctx.modal({title:p.enabled?'Désactiver cette règle':'Activer cette règle',subtitle:p.title,submitLabel:p.enabled?'Désactiver':'Activer',body:`<p>${p.enabled?'Cette règle ne sera plus considérée comme active dans le cadre de gouvernance de cette démonstration.':'Cette règle sera réintégrée au cadre de gouvernance actif de cette démonstration.'}</p><div class="field"><label for="policy-reason">Motif</label><textarea id="policy-reason" name="reason" required rows="3" maxlength="700" placeholder="Documentez la raison de ce changement…"></textarea></div>`,onSubmit:data=>{const reason=String(data.get('reason')||'').trim();if(!reason){ctx.toast('Documentez le motif de ce changement.');return false;}ctx.update(st=>{const current=st.policies.find(x=>x.id===p.id);current.enabled=!current.enabled;},p.enabled?'Règle désactivée':'Règle activée',`${p.title} — ${reason}`);ctx.toast('Le statut de la règle est mis à jour.');}});return true;
 }
 return false;
}
